// HAND-WRITTEN TEST — NOT generated by openapi-generator. The zz_ prefix and
// _test.go suffix keep gen.sh from overwriting it.
//
// It checks that DocumentTransfer selects its variant by transferMode.
package v1

import (
	"encoding/base64"
	"encoding/json"
	"strings"
	"testing"
)

// sha256Digest is 32 bytes, in base64.
var sha256Digest = base64.StdEncoding.EncodeToString(make([]byte, 32))

func TestDocumentTransferDecodesInline(t *testing.T) {
	var d DocumentTransfer
	if err := json.Unmarshal([]byte(`{"transferMode":"inline","document":"aGk="}`), &d); err != nil {
		t.Fatal(err)
	}
	if d.DigestOnlyDocumentTransfer != nil || d.InlineDocumentTransfer == nil {
		t.Fatalf("variant: %+v", d)
	}
	doc, err := base64.StdEncoding.DecodeString(d.InlineDocumentTransfer.Document)
	if err != nil || string(doc) != "hi" {
		t.Fatalf("document: %q, %v", doc, err)
	}
}

func TestDocumentTransferDecodesDigestOnly(t *testing.T) {
	var d DocumentTransfer
	raw := `{"transferMode":"digestOnly","documentDigest":"` + sha256Digest + `","digestAlgorithm":"SHA-256"}`
	if err := json.Unmarshal([]byte(raw), &d); err != nil {
		t.Fatal(err)
	}
	if d.InlineDocumentTransfer != nil || d.DigestOnlyDocumentTransfer == nil {
		t.Fatalf("variant: %+v", d)
	}
	v := d.DigestOnlyDocumentTransfer
	if v.DocumentDigest != sha256Digest || v.DigestAlgorithm != DIGESTALGORITHM_SHA_256 {
		t.Fatalf("fields: %+v", v)
	}
}

func TestDocumentTransferRefusesUnknownMode(t *testing.T) {
	for _, raw := range []string{`{"transferMode":"byReference","document":"aGk="}`, `{"document":"aGk="}`} {
		var d DocumentTransfer
		if err := json.Unmarshal([]byte(raw), &d); err == nil || !strings.Contains(err.Error(), "unknown transferMode") {
			t.Fatalf("%s: %v", raw, err)
		}
	}
}
